import type { Host } from './host'

export type BriefSource = { kind: 'jira'; key: string } | { kind: 'github'; ref: string } | { kind: 'text'; text: string }
export type Brief = { label: string; text: string }
type Result = { ok: true; brief: Brief } | { ok: false; error: string }
type McpResult = { content: { text?: string }[]; isError: boolean }

const RESOURCES_TOOL = 'getAccessibleAtlassianResources'
const ISSUE_TOOL = 'getJiraIssue'

const JIRA_KEY = /^[A-Z][A-Z0-9]+-\d+$/
const GITHUB_NUMBER = /^#(\d+)$/
const GITHUB_ISSUE_URL = /^https:\/\/github\.com\/[^/\s]+\/[^/\s]+\/issues\/(\d+)$/

const BUNDLED_SERVER = 'atlassian'

const JIRA_NOT_CONNECTED = 'Jira not connected; paste the ticket with --brief "..."'
const JIRA_SIGN_IN = 'Atlassian needs you to sign in: run /mcp, or paste the ticket with --brief "..."'
export const GH_UNAVAILABLE = 'gh is not available: run gh auth login'

export function classifyBrief(value: string): BriefSource {
  if (JIRA_KEY.test(value)) return { kind: 'jira', key: value }
  const number = GITHUB_NUMBER.exec(value)
  if (number) return { kind: 'github', ref: number[1]! }
  if (GITHUB_ISSUE_URL.test(value)) return { kind: 'github', ref: value }
  return { kind: 'text', text: value }
}

export async function fetchBrief(host: Host, source: BriefSource): Promise<Result> {
  if (source.kind === 'text') return { ok: true, brief: { label: 'pasted brief', text: source.text } }
  return source.kind === 'jira' ? fetchJira(host, source.key) : fetchGithub(host, source.ref)
}

// The plugin bundles the Atlassian server in .mcp.json; `connect` answers with
// the name to call it by, or with the name of the same server the session
// already runs. Anything else falls back to the tool-name search below.
async function atlassianServer(host: Host): Promise<{ server: string } | { error: string }> {
  const bundled = await host.mcpConnect(BUNDLED_SERVER).catch(() => undefined)
  if (bundled?.isConnected) return { server: bundled.server }
  const running = await runningAtlassianServer(host)
  if (running !== undefined) return { server: running }
  return { error: bundled?.reason === 'auth' ? JIRA_SIGN_IN : JIRA_NOT_CONNECTED }
}

// Servers cannot be listed, so one the session runs is found from the names of
// the MCP tools it carries (`mcp__<server>__<tool>`).
async function runningAtlassianServer(host: Host): Promise<string | undefined> {
  const tools = await host.mcpTools().catch(() => [])
  for (const name of tools) {
    const match = /^mcp__(.+)__([^_]+)$/.exec(name)
    const [, server, tool] = match ?? []
    if (server !== undefined && /atlassian/i.test(server) && tool === ISSUE_TOOL) return server
  }
  return undefined
}

// A call that rejects (a server gone mid-session) reads as one that failed.
async function callJson(host: Host, server: string, tool: string, args: Record<string, unknown>): Promise<unknown> {
  try {
    const { content, isError } = (await host.mcpCall(server, tool, args)) as McpResult
    return isError ? undefined : JSON.parse(content.map(b => b.text ?? '').join(''))
  } catch {
    return undefined
  }
}

const descriptionText = (description: unknown): string => {
  if (description === undefined || description === null) return ''
  return typeof description === 'string' ? description : JSON.stringify(description)
}

async function fetchJira(host: Host, key: string): Promise<Result> {
  const failed: Result = { ok: false, error: JIRA_NOT_CONNECTED }
  const found = await atlassianServer(host)
  if ('error' in found) return { ok: false, error: found.error }
  const { server } = found

  const resources = await callJson(host, server, RESOURCES_TOOL, {})
  const cloudId = Array.isArray(resources) ? (resources[0] as { id?: string } | undefined)?.id : undefined
  if (cloudId === undefined) return failed

  const issue = (await callJson(host, server, ISSUE_TOOL, { cloudId, issueIdOrKey: key })) as
    | { fields?: { summary?: string; description?: unknown } }
    | undefined
  if (issue?.fields === undefined) return { ok: false, error: `Could not read ${key} from Jira; paste the ticket with --brief "..."` }

  const { summary = '', description } = issue.fields
  return { ok: true, brief: { label: key, text: `${key}: ${summary}\n\n${descriptionText(description)}` } }
}

async function fetchGithub(host: Host, ref: string): Promise<Result> {
  const failed: Result = { ok: false, error: GH_UNAVAILABLE }
  const number = /\d+$/.exec(ref)?.[0] ?? ref
  const run = await host.run(['gh', 'issue', 'view', ref, '--json', 'title,body'])
  if (run.exitCode !== 0) return failed
  try {
    const { title, body } = JSON.parse(run.stdout) as { title: string; body: string }
    return { ok: true, brief: { label: `#${number}`, text: `#${number}: ${title}\n\n${body}` } }
  } catch {
    return failed
  }
}

files.hooks/findings.ts:
import type { Finding, Location, Review, Severity, Unparsed } from '../types'

export const OUTPUT_CONTRACT = [
  'End your answer with exactly one fenced ```json block of the form { "findings": [...] }.',
  'Each finding has these fields:',
  '- "severity": one of "critical", "high", "medium", "low".',
  '- "location": { "file": "<path>", "line": <number, optional> } for code, or { "section": "<heading>" } for a plan or document.',
  '- "claim": what is wrong, in one or two sentences.',
  '- "evidence": the concrete text, code or behaviour that shows it.',
  'Do not suggest fixes. If nothing is wrong, return { "findings": [] }.',
].join('\n')

export const DRAFT_OPENING =
  'An independent reviewer raised these findings. For each one, either fix it or reject it with a specific reason. Do not skip any.'

const SEVERITIES: Severity[] = ['critical', 'high', 'medium', 'low']

const slashes = (path: string) => path.replace(/\\/g, '/')

export const relativeTo = (root: string, file: string): string => {
  const prefix = slashes(root).replace(/\/+$/, '') + '/'
  const normal = slashes(file)
  return normal.toLowerCase().startsWith(prefix.toLowerCase()) ? normal.slice(prefix.length) : file
}

const isText = (value: unknown): value is string => typeof value === 'string' && value.trim() !== ''

const readLocation = (value: unknown, root: string): Location | string => {
  if (typeof value !== 'object' || value === null) return 'location must be an object'
  const { file, line, section } = value as Record<string, unknown>
  if (isText(section)) return { section }
  if (!isText(file)) return 'location needs a file or a section'
  if (line === undefined || line === null) return { file: relativeTo(root, file) }
  if (typeof line !== 'number' || !Number.isInteger(line)) return 'location.line must be an integer'
  return { file: relativeTo(root, file), line }
}

const readFinding = (value: unknown, id: number, root: string): Finding | string => {
  if (typeof value !== 'object' || value === null) return 'finding must be an object'
  const { severity, location, claim, evidence } = value as Record<string, unknown>
  if (!SEVERITIES.includes(severity as Severity)) return `severity must be one of ${SEVERITIES.join(', ')}`
  const where = readLocation(location, root)
  if (typeof where === 'string') return where
  if (!isText(claim)) return 'claim must be text'
  if (!isText(evidence)) return 'evidence must be text'
  return { id, severity: severity as Severity, location: where, claim, evidence, decision: 'undecided' }
}

const lastJsonBlock = (output: string): string | undefined => {
  const blocks = [...output.matchAll(/```json[^\S\n]*\n([\s\S]*?)^```[^\S\n]*$/gm)]
  return blocks.at(-1)?.[1]
}

export const parseFindings = (
  output: string,
  root: string,
): { ok: true; findings: Finding[]; unparsed: Unparsed[] } | { ok: false; error: 'no json block' } => {
  const body = lastJsonBlock(output)
  if (body === undefined) return { ok: false, error: 'no json block' }

  let parsed: unknown
  try {
    parsed = JSON.parse(body)
  } catch (error) {
    return { ok: true, findings: [], unparsed: [{ raw: body.trim(), reason: `invalid JSON: ${(error as Error).message}` }] }
  }

  const items = (parsed as { findings?: unknown } | null)?.findings
  if (!Array.isArray(items)) {
    return { ok: true, findings: [], unparsed: [{ raw: body.trim(), reason: 'no findings array' }] }
  }

  const findings: Finding[] = []
  const unparsed: Unparsed[] = []
  for (const item of items) {
    const result = readFinding(item, findings.length + 1, root)
    if (typeof result === 'string') unparsed.push({ raw: JSON.stringify(item), reason: result })
    else findings.push(result)
  }
  return { ok: true, findings, unparsed }
}

export const sortBySeverity = (findings: Finding[]): Finding[] =>
  findings
    .map((finding, index) => ({ finding, index }))
    .sort((a, b) => SEVERITIES.indexOf(a.finding.severity) - SEVERITIES.indexOf(b.finding.severity) || a.index - b.index)
    .map(({ finding }) => finding)

export const whereText = (location: Location): string => {
  if ('section' in location) return `§ ${location.section}`
  return location.line === undefined ? location.file : `${location.file}:${location.line}`
}

export const draftText = (findings: Finding[]): string => {
  const lines = findings
    .filter(finding => finding.decision === 'send')
    .flatMap((finding, index) => [
      `${index + 1}. [${finding.severity.toUpperCase()}] ${whereText(finding.location)} — ${finding.editedClaim ?? finding.claim}`,
      `   Evidence: ${finding.evidence}`,
    ])
  return [DRAFT_OPENING, '', ...lines].join('\n')
}

export const savedMarkdown = (review: Review, date: string): string => {
  const lines = [`# Adversarial review: ${review.kind} ${review.target}`, '', `Date: ${date}`, '']
  for (const finding of review.findings) {
    lines.push(
      `## ${finding.id}. [${finding.severity.toUpperCase()}] ${whereText(finding.location)} (${finding.decision})`,
      '',
      finding.editedClaim === undefined ? finding.claim : `${finding.editedClaim}`,
      '',
    )
    if (finding.editedClaim !== undefined) lines.push(`Original claim: ${finding.claim}`, '')
    lines.push(`Evidence: ${finding.evidence}`, '')
  }
  if (review.unparsed.length > 0) {
    lines.push('## Unparsed', '')
    for (const entry of review.unparsed) lines.push(`- ${entry.reason}: ${entry.raw}`)
    lines.push('')
  }
  return lines.join('\n')
}

